import type { StepInput } from '../schema';
import type { LessonGuidance, LessonUpgrade } from './types';

const guide = (goal: string, startingPoint: string, strategy: string[], selfCheck: string[]): LessonGuidance => ({ goal, startingPoint, strategy, selfCheck });
const scene = (id: string, prompt: string, situation: string, options: string[], answer: string, why: string): StepInput => ({ kind: 'scene', id, prompt, situation, options, answer, why });
const recall = (id: string, prompt: string, clue: string, before: string, after: string, answers: [string, ...string[]], why: string): StepInput => ({ kind: 'recall', id, prompt, clue, before, after, answers, word: answers[0], why });
const sort = (id: string, prompt: string, buckets: string[], items: [string, number][], why: string): StepInput => ({ kind: 'sort', id, prompt, buckets, items: items.map(([t, b]) => ({ t, b })), why });
const compose = (id: string, prompt: string, situation: string, target: string, forms: string[], models: string[], checks: string[], minWords = 20): StepInput => ({ kind: 'use', id, prompt, situation, targets: [{ word: target, forms }], minWords, models, checks });

